// Filter Stocks Based on User Preferences
const user = $('Loop Through Users').item.json;
const preferences = $input.all()[0].json[0] || {};
const allStocks = $('Get Today\'s Stock Analysis').all().map(item => {
  const detailed = JSON.parse(item.json.detailed_analysis || '{}');
  return {
    ...item.json,
    ...detailed
  };
});

console.log(`Filtering stocks for user: ${user.email}`);
console.log(`User tier: ${user.subscription_tier}`);
console.log(`Total stocks available: ${allStocks.length}`);

// Apply tier limits
let maxStocks = 5; // Free tier default
if (user.subscription_tier === 'pro') maxStocks = 20;
if (user.subscription_tier === 'enterprise') maxStocks = 50;

// Apply user preferences
const thresholdAmount = preferences.threshold_amount || 50000;
const watchlistSymbols = preferences.watchlist_symbols || [];
const excludedSymbols = preferences.excluded_symbols || [];
const minTransactionValue = preferences.min_transaction_value || 0;
const includeBuys = preferences.include_buys !== false;
const includeSells = preferences.include_sells !== false;

// Filter stocks
let filteredStocks = allStocks.filter(stock => {
  // Exclude symbols
  if (excludedSymbols.includes(stock.symbol)) {
    return false;
  }

  // Watchlist (if specified, only include these)
  if (watchlistSymbols.length > 0 && !watchlistSymbols.includes(stock.symbol)) {
    return false;
  }

  // Threshold
  if (Math.abs(stock.net_money_flow || 0) < thresholdAmount) {
    return false;
  }

  // Min transaction value
  if (Math.abs(stock.net_money_flow || 0) < minTransactionValue) {
    return false;
  }

  // Buy/Sell preferences
  const isBuy = (stock.net_money_flow || 0) > 0;
  const isSell = (stock.net_money_flow || 0) < 0;

  if (isBuy && !includeBuys) return false;
  if (isSell && !includeSells) return false;

  return true;
});

// Apply max stocks limit
filteredStocks = filteredStocks.slice(0, maxStocks);

console.log(`Filtered to ${filteredStocks.length} stocks for ${user.email}`);

if (filteredStocks.length === 0) {
  return [{
    json: {
      user: user,
      preferences: preferences,
      stocks: [],
      shouldSendAlert: false,
      message: 'No stocks match user preferences'
    }
  }];
}

return [{
  json: {
    user: user,
    preferences: preferences,
    stocks: filteredStocks,
    shouldSendAlert: true,
    stockCount: filteredStocks.length
  }
}];

// Format Email Alert Message
const data = $input.all()[0].json;
const user = data.user;
const stocks = data.stocks;

const dateStr = new Date().toLocaleDateString('en-US', { 
  month: 'short', 
  day: 'numeric', 
  year: 'numeric' 
});

let emailBody = `
<html>
<head>
  <style>
    body { font-family: Arial, sans-serif; line-height: 1.6; color: #333; }
    .header { background: #2563eb; color: white; padding: 20px; text-align: center; }
    .content { padding: 20px; }
    .stock { background: #f3f4f6; border-left: 4px solid #2563eb; padding: 15px; margin: 20px 0; }
    .buy { border-left-color: #10b981; }
    .sell { border-left-color: #ef4444; }
    .metric { display: inline-block; margin: 10px 20px 10px 0; }
    .footer { background: #f3f4f6; padding: 20px; text-align: center; font-size: 12px; color: #666; }
  </style>
</head>
<body>
  <div class="header">
    <h1>🚨 Insider Trading Alert</h1>
    <p>${dateStr}</p>
  </div>
  <div class="content">
    <p>Hi there,</p>
    <p>We've detected <strong>${stocks.length} significant insider trading activities</strong> that match your preferences:</p>
`;

stocks.forEach((stock, index) => {
  const isBuy = (stock.net_money_flow || 0) > 0;
  const emoji = isBuy ? '📈' : '📉';
  const className = isBuy ? 'stock buy' : 'stock sell';

  const flowMM = Math.abs(stock.net_money_flow || 0) / 1000000;
  const flowFormatted = `$${flowMM.toFixed(2)}M`;

  const topInsiders = stock.topInsiders || [];
  const topInsider = topInsiders[0];

  emailBody += `
    <div class="${className}">
      <h2>${emoji} #${index + 1}: ${stock.symbol}</h2>
      <div class="metric">
        <strong>Net Activity:</strong> ${flowFormatted} ${isBuy ? '(BUYING)' : '(SELLING)'}
      </div>
      <div class="metric">
        <strong>Insiders:</strong> ${stock.total_insiders || 0} (${stock.buyers_count || 0} buying, ${stock.sellers_count || 0} selling)
      </div>
      <div class="metric">
        <strong>Recommendation:</strong> ${stock.recommendation || 'N/A'}
      </div>
      <div class="metric">
        <strong>Confidence:</strong> ${stock.confidence_level || 'N/A'}
      </div>
  `;

  if (topInsider) {
    emailBody += `
      <p><strong>Top Insider Activity:</strong></p>
      <p>${topInsider.name} ${topInsider.activity === 'BUYING' ? 'BOUGHT' : 'SOLD'} ${topInsider.netValueFormatted}</p>
    `;
  }

  emailBody += `
    </div>
  `;
});

emailBody += `
    <p>For more details, <a href="${process.env.NEXT_PUBLIC_APP_URL || 'https://yourdomain.com'}/dashboard">visit your dashboard</a>.</p>
  </div>
  <div class="footer">
    <p>This alert was generated based on your preferences. <a href="${process.env.NEXT_PUBLIC_APP_URL || 'https://yourdomain.com'}/settings">Update your preferences</a></p>
    <p>&copy; ${new Date().getFullYear()} InsiderAlerts. All rights reserved.</p>
  </div>
</body>
</html>
`;

return [{
  json: {
    user: user,
    subject: `🚨 ${stocks.length} Insider Trading Alert${stocks.length > 1 ? 's' : ''} - ${dateStr}`,
    emailBody: emailBody,
    stocks: stocks
  }
}];

// Format Telegram Alert Message
const data = $input.all()[0].json;
const user = data.user;
const stocks = data.stocks;

const dateStr = new Date().toLocaleDateString('en-US', { 
  month: 'short', 
  day: 'numeric', 
  year: 'numeric' 
});

let message = `🔔 INSIDER TRADING ALERT\n${dateStr}\n\n`;

stocks.slice(0, 5).forEach((stock, index) => {
  const isBuy = (stock.net_money_flow || 0) > 0;
  const emoji = isBuy ? '📈' : '📉';

  const flowMM = Math.abs(stock.net_money_flow || 0) / 1000000;
  const flowFormatted = `$${flowMM.toFixed(2)}M`;

  const topInsiders = stock.topInsiders || [];
  const topInsider = topInsiders[0];

  message += `${emoji} #${index + 1} ${stock.symbol}\n`;

  if (topInsider) {
    message += `${topInsider.name} ${topInsider.activity === 'BUYING' ? 'BOUGHT' : 'SOLD'} ${topInsider.netValueFormatted}\n`;
  } else {
    message += `Net: ${flowFormatted} ${isBuy ? '(BUY)' : '(SELL)'}\n`;
  }

  message += `Signal: ${stock.recommendation || 'N/A'}\n\n`;
});

if (stocks.length > 5) {
  message += `📧 +${stocks.length - 5} more in email\n\n`;
}

message += `📊 View details in your dashboard`;

return [{
  json: {
    user: user,
    message: message,
    stocks: stocks
  }
}];
